{
  "name": "trellis-daily-f3-shared-expenses",
  "version": "1.0.0",
  "private": true,
  "description": "Frozen family-3 fixture for the 2026-09-09 daily-workflow eval. Green baseline plus authoritative project facts that a follow-up change must consume.",
  "scripts": {
    "test": "node --test test/"
  }
}

'use strict';

// Every monetary amount in this project is an integer number of minor units
// (cents). See docs/decisions/2026-08-24-integer-minor-units.md.
function assertMinorUnits(amount) {
  if (!Number.isInteger(amount)) {
    throw new TypeError(
      `amount must be an integer number of minor units, received: ${amount}`,
    );
  }
  return amount;
}

function addAmounts(amounts) {
  return amounts.reduce((total, amount) => total + assertMinorUnits(amount), 0);
}

// Splits one expense evenly between `people`. The remainder is handed out one
// minor unit at a time to the leading shares, so the shares always add back up
// to `amount` exactly and differ by at most one minor unit.
function splitAmount(amount, people) {
  assertMinorUnits(amount);
  if (!Number.isInteger(people) || people < 1) {
    throw new RangeError(
      `people must be a positive integer, received: ${people}`,
    );
  }

  const base = Math.trunc(amount / people);
  const remainder = amount - base * people;
  const step = remainder < 0 ? -1 : 1;

  return Array.from({ length: people }, (_unused, index) =>
    index < Math.abs(remainder) ? base + step : base,
  );
}

// Display boundary: the only place where an amount becomes a decimal string.
function formatAmount(amount) {
  assertMinorUnits(amount);
  const sign = amount < 0 ? '-' : '';
  const abs = Math.abs(amount);
  return `${sign}${Math.trunc(abs / 100)}.${String(abs % 100).padStart(2, '0')}`;
}

// Display boundary: one pasteable line describing a split. Shares are grouped
// by value instead of listed one by one, so the line stays short no matter how
// many people share the bill.
function summarizeSplit(amount, people) {
  const shares = splitAmount(amount, people);

  const headCountByShare = new Map();
  for (const share of shares) {
    headCountByShare.set(share, (headCountByShare.get(share) || 0) + 1);
  }

  const perPerson =
    headCountByShare.size === 1
      ? `每人 ${formatAmount(shares[0])}`
      : [...headCountByShare]
          .map(([share, headCount]) => `${headCount} 人 ${formatAmount(share)}`)
          .join('，');

  return `合计 ${formatAmount(amount)}，${people} 人平摊：${perPerson}`;
}

module.exports = {
  addAmounts,
  splitAmount,
  formatAmount,
  summarizeSplit,
  assertMinorUnits,
};

'use strict';

const { test } = require('node:test');
const assert = require('node:assert/strict');

const { splitAmount, formatAmount } = require('../src/money');

test('an evenly divisible amount splits into equal shares', () => {
  assert.deepEqual(splitAmount(1200, 4), [300, 300, 300, 300]);
  assert.deepEqual(splitAmount(1000, 1), [1000]);
  assert.deepEqual(splitAmount(0, 3), [0, 0, 0]);
});

test('the remainder is handed out, never dropped', () => {
  assert.deepEqual(splitAmount(1000, 3), [334, 333, 333]);
  assert.deepEqual(splitAmount(1, 3), [1, 0, 0]);
  assert.deepEqual(splitAmount(1234, 5), [247, 247, 247, 247, 246]);
});

test('shares always add back up to the original amount', () => {
  for (const total of [0, 1, 5, 99, 100, 1234, 100003, -1, -1234, -100003]) {
    for (let people = 1; people <= 7; people += 1) {
      const shares = splitAmount(total, people);
      assert.equal(shares.length, people);
      assert.equal(
        shares.reduce((sum, share) => sum + share, 0),
        total,
        `${total} split ${people} ways must be conserved`,
      );
    }
  }
});

test('a negative amount splits without gaining or losing a minor unit', () => {
  assert.deepEqual(splitAmount(-1000, 3), [-334, -333, -333]);
});

test('shares differ by at most one minor unit', () => {
  const shares = splitAmount(100003, 7);
  assert.equal(Math.max(...shares) - Math.min(...shares), 1);
});

test('a non-integer amount or a bad head count is rejected', () => {
  assert.throws(() => splitAmount(12.34, 2), TypeError);
  assert.throws(() => splitAmount('1234', 2), TypeError);
  assert.throws(() => splitAmount(1200, 0), RangeError);
  assert.throws(() => splitAmount(1200, -2), RangeError);
  assert.throws(() => splitAmount(1200, 2.5), RangeError);
});

test('a split share is displayed through the shared display boundary', () => {
  assert.deepEqual(splitAmount(1000, 3).map(formatAmount), [
    '3.34',
    '3.33',
    '3.33',
  ]);
});

'use strict';

const { test } = require('node:test');
const assert = require('node:assert/strict');

const { summarizeSplit, splitAmount, formatAmount } = require('../src/money');

test('an even split collapses to a single per-person figure', () => {
  assert.equal(summarizeSplit(1200, 4), '合计 12.00，4 人平摊：每人 3.00');
  assert.equal(summarizeSplit(1000, 1), '合计 10.00，1 人平摊：每人 10.00');
});

test('an uneven split names how many people pay each share', () => {
  assert.equal(summarizeSplit(1000, 3), '合计 10.00，3 人平摊：1 人 3.34，2 人 3.33');
  assert.equal(summarizeSplit(1234, 5), '合计 12.34，5 人平摊：4 人 2.47，1 人 2.46');
});

test('the summary stays one line however many people share the bill', () => {
  const summary = summarizeSplit(100003, 7);
  assert.doesNotMatch(summary, /\n/);
  assert.equal(summary, '合计 1000.03，7 人平摊：1 人 142.87，6 人 142.86');
});

test('a negative amount is summarized without losing a minor unit', () => {
  assert.equal(summarizeSplit(-1000, 3), '合计 -10.00，3 人平摊：1 人 -3.34，2 人 -3.33');
});

test('every amount in the summary comes from the shared display boundary', () => {
  for (const total of [0, 1, 99, 1234, 100003, -1234]) {
    for (let people = 1; people <= 7; people += 1) {
      const summary = summarizeSplit(total, people);
      assert.ok(
        summary.startsWith(`合计 ${formatAmount(total)}，`),
        `${total} split ${people} ways must report the formatted total`,
      );
      for (const share of new Set(splitAmount(total, people))) {
        assert.ok(
          summary.includes(` ${formatAmount(share)}`),
          `${total} split ${people} ways must report share ${share} formatted`,
        );
      }
    }
  }
});

test('the head counts in the summary add up to the people sharing the bill', () => {
  for (const total of [0, 1, 99, 1234, 100003, -1234]) {
    for (let people = 2; people <= 7; people += 1) {
      const counts = [...summarizeSplit(total, people).matchAll(/(\d+) 人 /g)].map(
        (match) => Number(match[1]),
      );
      if (counts.length > 0) {
        assert.equal(
          counts.reduce((sum, count) => sum + count, 0),
          people,
          `${total} split ${people} ways must account for every person`,
        );
      }
    }
  }
});

test('a non-integer amount or a bad head count is rejected', () => {
  assert.throws(() => summarizeSplit(12.34, 2), TypeError);
  assert.throws(() => summarizeSplit('1234', 2), TypeError);
  assert.throws(() => summarizeSplit(1200, 0), RangeError);
  assert.throws(() => summarizeSplit(1200, 2.5), RangeError);
});

